const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Sumatra and Borneo, Indonesia
  const sumatra = ee.Geometry.Polygon([
    [[95, 6], [95, -6], [106, -6], [106, 6]]
  ]);

  const borneo = ee.Geometry.Polygon([
    [[108, 7], [108, -5], [120, -5], [120, 7]]
  ]);

  const region = ee.Geometry.MultiPolygon([sumatra, borneo]);

  // 2. Data Acquisition - FIRMS Active Fires
  const fires2022 = ee.ImageCollection('FIRMS')
    .filterDate('2022-01-01', '2022-12-31')
    .filterBounds(region);

  const fires2023 = ee.ImageCollection('FIRMS')
    .filterDate('2023-01-01', '2023-12-31')
    .filterBounds(region);

  // Check if collections exist
  const count2022 = fires2022.size().getInfo();
  const count2023 = fires2023.size().getInfo();

  console.log(`2022 Images: ${count2022}`);
  console.log(`2023 Images: ${count2023}`);

  if (count2022 === 0 && count2023 === 0) {
    console.log('No fire data found for either year.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Try alternative: MODIS thermal anomalies
  const modis2022 = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate('2022-01-01', '2022-12-31')
    .filterBounds(region)
    .select('FireMask');

  const modis2023 = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate('2023-01-01', '2023-12-31')
    .filterBounds(region)
    .select('FireMask');

  const modisCount2022 = modis2022.size().getInfo();
  const modisCount2023 = modis2023.size().getInfo();

  console.log(`2022 MODIS Images: ${modisCount2022}`);
  console.log(`2023 MODIS Images: ${modisCount2023}`);

  if (modisCount2022 === 0 || modisCount2023 === 0) {
    console.log('Insufficient MODIS data.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Count fire pixels (FireMask > 7 indicates fire detection)
  const firePixels2022 = modis2022.map(img => img.gt(7)).sum();
  const firePixels2023 = modis2023.map(img => img.gt(7)).sum();

  // 4. Calculate total fire detections
  const stats2022 = firePixels2022.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2023 = firePixels2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const total2022 = stats2022.get('FireMask').getInfo();
  const total2023 = stats2023.get('FireMask').getInfo();

  console.log(`2022 Fire Detections: ${total2022}`);
  console.log(`2023 Fire Detections: ${total2023}`);

  // 5. Validation & Final Answer
  if (total2022 === null || total2023 === null || 
      isNaN(total2022) || isNaN(total2023)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  const increase = total2023 - total2022;
  const percentChange = ((increase / total2022) * 100).toFixed(1);

  console.log(`Change: ${increase} (${percentChange}%)`);

  if (total2023 > total2022) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
